use serde_json::{json,Value};
use sysinfo::{System,Disks,Networks,ProcessesToUpdate};
pub struct Monitor {pub system:System,pub process_system:System,pub networks:Networks,pub last:std::time::Instant}
impl Monitor {pub fn new()->Self{let mut system=System::new_all();std::thread::sleep(sysinfo::MINIMUM_CPU_UPDATE_INTERVAL);system.refresh_all();Self{system,process_system:System::new_all(),networks:Networks::new_with_refreshed_list(),last:std::time::Instant::now()}}
pub fn snapshot(&mut self)->Value{let since=self.last.elapsed();if since<sysinfo::MINIMUM_CPU_UPDATE_INTERVAL{std::thread::sleep(sysinfo::MINIMUM_CPU_UPDATE_INTERVAL-since);}let elapsed=self.last.elapsed().as_secs_f64().max(0.001);self.system.refresh_all();self.networks.refresh(true);self.last=std::time::Instant::now();let s=&self.system;let disks=Disks::new_with_refreshed_list();json!({"timestamp":std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap_or_default().as_millis() as u64,"cpu_model":s.cpus().first().map(|c|c.brand()).unwrap_or("Não disponível"),"cpu_percent":s.global_cpu_usage(),"cores":s.cpus().len(),"per_core":s.cpus().iter().map(|c|c.cpu_usage()).collect::<Vec<_>>(),"ram_total":s.total_memory(),"ram_used":s.used_memory(),"uptime":System::uptime(),"os":System::long_os_version(),"processes":s.processes().len(),"disks":disks.iter().map(|d|json!({"name":d.mount_point().to_string_lossy(),"total":d.total_space(),"free":d.available_space()})).collect::<Vec<_>>(),"network_rx":self.networks.iter().map(|(_,n)|n.received() as f64/elapsed).sum::<f64>(),"network_tx":self.networks.iter().map(|(_,n)|n.transmitted() as f64/elapsed).sum::<f64>()})}
pub fn processes(&mut self)->Value{self.process_system.refresh_processes(ProcessesToUpdate::All,true);json!(self.process_system.processes().iter().map(|(pid,p)|json!({"PID":pid.as_u32(),"Nome":p.name().to_string_lossy(),"CPU":p.cpu_usage()/self.system.cpus().len().max(1) as f32,"RAM":p.memory(),"Leitura":p.disk_usage().read_bytes,"Escrita":p.disk_usage().written_bytes,"Caminho":p.exe().map(|x|x.to_string_lossy().to_string()),"Pai":p.parent().map(|p|p.as_u32()),"Início":p.start_time(),"Assinatura":"Não disponível","Rede":"Não disponível"})).collect::<Vec<_>>())}}
